# Surah Al-A'raf (chapter 7) — part 9: ayat 85-94 (IDs 1039-1048)
SURAH = 7

ENTRIES = {
1039: (
"اور — مدین کی طرف — ان کے بھائی شعیبؑ کو بھیجا — انہوں نے کہا — اے میری قوم — اللہ کی عبادت کرو — تمہارے لیے — اس کے علاوہ کوئی الٰہ نہیں — بے شک — تمہارے پاس — تمہارے رب — کی طرف سے — ایک واضح نشانی آئی — پس — ناپ اور تول پورا کرو — اور — لوگوں کو — ان کی اشیاء — کم نہ دو — اور — زمین میں — اس کی اصلاح کے بعد فساد نہ کرو — یہ — تمہارے لیے بہتر ہے — اگر — تم — مؤمن ہو",
"""۱۔ شعیبؑ — مدین کی طرف — معاشی انصاف کی دعوت۔
۲۔ ’’وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ قَدْ جَاءَتْكُم بَيِّنَۃٌ مِّن رَّبِّكُمْ فَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ‘‘ — اور — مدین کی طرف — ان کے بھائی شعیبؑ کو بھیجا — انہوں نے کہا — اے میری قوم — اللہ کی عبادت کرو — تمہارے لیے — اس کے علاوہ کوئی الٰہ نہیں — بے شک — تمہارے پاس — تمہارے رب — کی طرف سے — ایک واضح نشانی آئی — پس — ناپ اور تول پورا کرو — اور — لوگوں کو — ان کی اشیاء — کم نہ دو — اور — زمین میں — اس کی اصلاح کے بعد فساد نہ کرو — یہ — تمہارے لیے بہتر ہے — اگر — تم — مؤمن ہو — یعنی توحید کے ساتھ — معاشی انصاف — بھی واجب ہے۔
۳۔ عملی سبق: ناپ تول میں ایمانداری — ایمان کا حصہ ہے۔"""
),
1040: (
"اور — ہر راستہ پر — مت بیٹھو — دھمکانے — اور — اللہ کے راستے سے — روکنے — اور — ایمان والوں کو — خوف زدہ کرنے اور — اسے ٹیڑھا کرنے کے لیے — اور یاد کرو — جب تم — تھوڑے تھے — تو اس نے تمہیں زیادہ کر دیا — اور — دیکھو — فساد کرنے والوں کا کیا انجام ہوا",
"""۱۔ راہزنی اور خوف زدہ کرنا — بڑا گناہ۔
۲۔ ’’وَلَا تَقْعُدُوا بِكُلِّ صِرَاطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ اللَّهِ مَنْ آمَنَ بِهِ وَتَبْغُونَهَا عِوَجًا وَاذْكُرُوا إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ وَانظُرُوا كَيْفَ كَانَ عَاقِبَۃُ الْمُفْسِدِينَ‘‘ — اور — ہر راستہ پر — مت بیٹھو — دھمکانے — اور — اللہ کے راستے سے — روکنے — اور — ایمان والوں کو — خوف زدہ کرنے اور — اسے ٹیڑھا کرنے کے لیے — اور یاد کرو — جب تم — تھوڑے تھے — تو اس نے تمہیں زیادہ کر دیا — اور — دیکھو — فساد کرنے والوں کا کیا انجام ہوا — یعنی ایمانداروں کو دھمکانا — اور راہ روکنا — اللہ ناپسند کرتا ہے۔
۳۔ عملی سبق: ایمانداروں کو ڈرانے سے بچو؛ اللہ — کثرت اور طاقت دینے والا ہے۔"""
),
1041: (
"اور — اگر — تم میں سے — ایک گروہ — اس — رسالت پر — جس — پر — میں بھیجا گیا ہوں — ایمان لایا — اور — ایک گروہ — ایمان نہیں لایا — تو صبر کرو — یہاں تک کہ — اللہ — ہمارے درمیان فیصلہ کرے — اور — وہ — بہترین فیصلہ کرنے والا ہے",
"""۱۔ شعیبؑ — اپنی قوم کو — صبر کی تلقین۔
۲۔ ’’وَإِن كَانَ طَائِفَۃٌ مِّنكُمْ آمَنُوا بِالَّذِي أُرْسِلْتُ بِهِ وَطَائِفَۃٌ لَّمْ يُؤْمِنُوا فَاصْبِرُوا حَتَّىٰ يَحْكُمَ اللَّهُ بَيْنَنَا وَهُوَ خَيْرُ الْحَاكِمِينَ‘‘ — اور — اگر — تم میں سے — ایک گروہ — اس — رسالت پر — جس — پر — میں بھیجا گیا ہوں — ایمان لایا — اور — ایک گروہ — ایمان نہیں لایا — تو صبر کرو — یہاں تک کہ — اللہ — ہمارے درمیان فیصلہ کرے — اور — وہ — بہترین فیصلہ کرنے والا ہے — یعنی اختلاف — اللہ کے فیصلے تک — صبر سے ٹالا جائے۔
۳۔ عملی سبق: جب حالات مشکل ہوں — صبر کرو؛ اللہ کا فیصلہ — بہترین ہے۔"""
),
1042: (
"ان کی قوم کے تکبر والے سرداروں نے کہا — ہم — تجھے — اے شعیبؑ — اور — جو — تیرے ساتھ — ایمان لائے ہیں — ضرور — اپنے شہر سے نکال دیں گے — یا — تم — ہمارے مذہب میں — واپس لوٹ آؤ — شعیبؑ نے کہا — کیا — اگرچہ ہم — ناپسند کرنے والے ہوں",
"""۱۔ شعیبؑ کو شہر بدر کرنے کی دھمکی۔
۲۔ ’’قَالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِن قَوْمِهِ لَنُخْرِجَنَّكَ يَا شُعَيْبُ وَالَّذِينَ آمَنُوا مَعَكَ مِن قَرْيَتِنَا أَوْ لَتَعُودُنَّ فِي مِلَّتِنَا قَالَ أَوَلَوْ كُنَّا كَارِهِينَ‘‘ — ان کی قوم کے تکبر والے سرداروں نے کہا — ہم — تجھے — اے شعیبؑ — اور — جو — تیرے ساتھ — ایمان لائے ہیں — ضرور — اپنے شہر سے نکال دیں گے — یا — تم — ہمارے مذہب میں — واپس لوٹ آؤ — شعیبؑ نے کہا — کیا — اگرچہ ہم — ناپسند کرنے والے ہوں — یعنی شعیبؑ کو دو آپشن دیے گئے: بے دخلی یا — بت پرستی کی واپسی۔
۳۔ عملی سبق: حق چھوڑنے سے — ملک بدری بہتر ہے۔"""
),
1043: (
"ہم — اللہ پر — جھوٹ گھڑیں گے — اگر — ہم — تمہارے مذہب میں واپس لوٹ آئیں — بعد اس کے — کہ — اللہ نے — ہمیں — اس سے بچا لیا — اور — ہمارے لیے — اس میں — واپس لوٹنا — جائز نہیں — مگر یہ — کہ — اللہ — ہمارا رب — چاہے — ہمارے رب — کا علم — ہر چیز پر محیط ہے — ہم — اللہ پر توکل کرتے ہیں — اے ہمارے رب — ہمارے اور ہماری قوم کے درمیان — حق کے ساتھ — فیصلہ کر — اور — تو — بہترین فیصلہ کرنے والا ہے",
"""۱۔ شعیبؑ — واضح انکار اور — اللہ پر توکل۔
۲۔ ’’قَدِ افْتَرَيْنَا عَلَى اللَّهِ كَذِبًا إِنْ عُدْنَا فِي مِلَّتِكُم بَعْدَ إِذْ نَجَّانَا اللَّهُ مِنْهَا وَمَا يَكُونُ لَنَا أَن نَّعُودَ فِيهَا إِلَّا أَن يَشَاءَ اللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَيْءٍ عِلْمًا عَلَى اللَّهِ تَوَكَّلْنَا رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنتَ خَيْرُ الْفَاتِحِينَ‘‘ — ہم — اللہ پر — جھوٹ گھڑیں گے — اگر — ہم — تمہارے مذہب میں واپس لوٹ آئیں — بعد اس کے — کہ — اللہ نے — ہمیں — اس سے بچا لیا — اور — ہمارے لیے — اس میں — واپس لوٹنا — جائز نہیں — مگر یہ — کہ — اللہ — ہمارا رب — چاہے — ہمارے رب — کا علم — ہر چیز پر محیط ہے — ہم — اللہ پر توکل کرتے ہیں — اے ہمارے رب — ہمارے اور ہماری قوم کے درمیان — حق کے ساتھ — فیصلہ کر — اور — تو — بہترین فیصلہ کرنے والا ہے — یعنی شعیبؑ — ایمان چھوڑنے سے — واضح انکار کرتے ہیں — اور اللہ سے فیصلہ مانگتے ہیں۔
۳۔ عملی سبق: حق پر قائم رہو؛ فیصلے — اللہ سے — مانگو۔"""
),
1044: (
"اور ان کی قوم کے کافر سرداروں نے کہا — اگر — تم — شعیبؑ کی — پیروی کرو — تو — تم — ضرور — نقصان پانے والوں میں سے ہو",
"""۱۔ سردار — شعیبؑ کو پیروی ترک کرنے کی دھمکی دیتے ہیں۔
۲۔ ’’وَقَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِن قَوْمِهِ لَئِنِ اتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَاسِرُونَ‘‘ — اور ان کی قوم کے کافر سرداروں نے کہا — اگر — تم — شعیبؑ کی — پیروی کرو — تو — تم — ضرور — نقصان پانے والوں میں سے ہو — یعنی سردار — خوفزدی کر کے — قوم کو شعیبؑ سے — دور رکھنا چاہتے ہیں۔
۳۔ عملی سبق: حق کی پیروی — کسی کے نقصان ہونے سے — بہتر ہے۔"""
),
1045: (
"پس — انہیں — زلزلہ — آ لیا — اور — وہ — اپنے گھروں میں — منہ کے بل گرے ہوئے — پڑے رہ گئے",
"""۱۔ مدین — زلزلے میں — ہلاک۔
۲۔ ’’فَأَخَذَتْهُمُ الرَّجْفَۃُ فَأَصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ‘‘ — پس — انہیں — زلزلہ — آ لیا — اور — وہ — اپنے گھروں میں — منہ کے بل گرے ہوئے — پڑے رہ گئے — یعنی ایک لمحے میں پوری قوم — ختم۔
۳۔ عملی سبق: اللہ کا عذاب — جب آتا ہے تو — دیکھتے ہی دیکھتے ہے۔"""
),
1046: (
"جنہوں نے شعیبؑ کو جھٹلایا — گویا — کہ — وہ — ان — گھروں میں — بہت عرصہ سے — رہے ہی نہیں — (ایسے ختم ہوئے) — جنہوں نے شعیبؑ کو جھٹلایا — وہی — نقصان پانے والے تھے",
"""۱۔ مدین کا — مکمل — خاتمہ۔
۲۔ ’’الَّذِينَ كَذَّبُوا شُعَيْبًا كَأَن لَّمْ يَغْنَوْا فِيهَا الَّذِينَ كَذَّبُوا شُعَيْبًا كَانُوا هُمُ الْخَاسِرِينَ‘‘ — جنہوں نے شعیبؑ کو جھٹلایا — گویا — کہ — وہ — ان — گھروں میں — بہت عرصہ سے — رہے ہی نہیں — (ایسے ختم ہوئے) — جنہوں نے شعیبؑ کو جھٹلایا — وہی — نقصان پانے والے تھے — یعنی مدین — زمین سے ایسے مٹ گئی — جیسے کبھی آباد ہی نہ تھی۔
۳۔ عملی سبق: جھٹلانے والوں کا انجام — یہی ہوتا ہے۔"""
),
1047: (
"پس — شعیبؑ — ان سے — واپس لوٹ آئے — اور کہا — اے میری قوم — بے شک — میں نے — تمہیں — اپنے رب کے پیغامات — پہنچائے — اور — تمہاری خیر خواہی کی — پس — میں — کافر قوم — پر کیسے — رنج کروں",
"""۱۔ شعیبؑ — قوم سے — الوداع۔
۲۔ ’’فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَاتِ رَبِّي وَنَصَحْتُ لَكُمْ فَكَيْفَ آسَىٰ عَلَىٰ قَوْمٍ كَافِرِينَ‘‘ — پس — شعیبؑ — ان سے — واپس لوٹ آئے — اور کہا — اے میری قوم — بے شک — میں نے — تمہیں — اپنے رب کے پیغامات — پہنچائے — اور — تمہاری خیر خواہی کی — پس — میں — کافر قوم — پر کیسے — رنج کروں — یعنی شعیبؑ— اپنی ذمہ داری پوری کر کے — قوم کو — اللہ کے حوالے کر دیتے ہیں۔
۳۔ عملی سبق: ذمہ داری پوری کرو؛ نتیجہ — اللہ پر چھوڑو۔"""
),
1048: (
"اور ہم نے — کسی بستی میں — کوئی نبی نہیں بھیجا — مگر — ہم نے — اس کے لوگوں کو — سختی اور مصیبت میں مبتلا کیا — تاکہ — وہ عاجزی اختیار کریں",
"""۱۔ مصیبت — یاد دہانی — اور — توبہ کا موقع۔
۲۔ ’’وَمَا أَرْسَلْنَا فِي قَرْيَۃٍ مِّن نَّبِيٍّ إِلَّا أَخَذْنَا أَهْلَهَا بِالْبَأْسَاءِ وَالضَّرَّاءِ لَعَلَّهُمْ يَضَّرَّعُونَ‘‘ — اور ہم نے — کسی بستی میں — کوئی نبی نہیں بھیجا — مگر — ہم نے — اس کے لوگوں کو — سختی اور مصیبت میں مبتلا کیا — تاکہ — وہ عاجزی اختیار کریں — یعنی نبی بھیجنے سے پہلے — یا بعد — سختی آتی ہے — تاکہ لوگ توبہ کریں۔
۳۔ عملی سبق: مصیبت — توبہ کا موقع ہے؛ عاجزی اختیار کرو۔"""
),
}
